        Map<E, E> edgeMap = new HashMap<>();
        for (E edge : copyGraph.edgeSet()) {
            edgeMap.put(edge, edge);
        }

        return new IsomorphicGraphMapping<V, E>(copyGraph, vertexMap, edgeMap);
