public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the input parameters are valid
    if (target == null) {
        throw new IllegalArgumentException("target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("result map cannot be null");
    }

    // Keep track of the vertices and edges added to the target graph
    Set<V> addedVertices = new HashSet<>();
    Set<E> addedEdges = new HashSet<>();

    // Iterate over the result map and add the vertices and edges to the target graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        // Get the vertex and its neighbors
        V vertex = entry.getValue();
        List<V> neighbors = getNeighbors(vertex);

        // Add the vertex to the target graph if it's not already added
        if (!addedVertices.contains(vertex)) {
            target.addVertex(vertex);
            addedVertices.add(vertex);
        }

        // Add the edges between the vertex and its neighbors
        for (V neighbor : neighbors) {
            E edge = target.addEdge(vertex, neighbor);
            addedEdges.add(edge);
        }
    }

    // Return the generated graph
    return target;
}

