 * Wraps a string of text to a specified number of characters using whitespace as a delimiter.
 */
private String wordWrap(final String text, final int width) {
    // Split the text into individual words
    String[] words = text.split("\\s+");

    // Initialize the wrapped text
    StringBuilder wrappedText = new StringBuilder();

    // Iterate over each word
    for (int i = 0; i < words.length; i++) {
        // Get the current word
        String word = words[i];

        // Check if the word is longer than the allowed width
        if (word.length() > width) {
            // If the word is too long, split it into smaller words and append them to the wrapped text
            List<String> splitWords = splitWord(word, width);
            for (String splitWord : splitWords) {
                wrappedText.append(splitWord).append(" ");
            }
        } else {
            // If the word is not too long, append it to the wrapped text
            wrappedText.append(word).append(" ");
        }
    }

    // Remove any trailing whitespace and return the wrapped text
    return wrappedText.toString().trim();
}

/**
 * Splits a word into smaller words based on a specified width
 */
private List<String> splitWord(final String word, final int width) {
    // Initialize the list of split words
    List<String> splitWords = new ArrayList<>();

    // Get the length of the word
    int wordLength = word.length();

    // Check if the word can be split evenly
    if (wordLength % width == 0) {
        // If the word can be split evenly, split it into equal parts
        int parts = wordLength / width;
        for (int i = 0; i < parts; i++) {
            splitWords.add(word.substring(i * width, (i + 1) * width));
        }
    } else {
        // If the word cannot be split evenly, split it into as many parts as possible while maintaining word boundaries
        int maxParts = wordLength / width + 1;
        for (int i = 0; i < maxParts; i++) {
            splitWords.add(word.substring(i * width, Math.min((i + 1) * width, wordLength)));
        }
    }

    // Return the list of split words
    return splitWords;
}

