    // Calculate the day of the month
    int dayOfMonth = (int) (timeBucket % 100);

    // Calculate the month
    int month = (int) ((timeBucket / 100) % 100);

    // Calculate the year
    int year = (int) (timeBucket / 10_000);

    // Calculate the new day of the month
    int newDayOfMonth = dayOfMonth - dayStep;

    // If the new day of the month is less than 1, add it to the month
    if (newDayOfMonth < 1) {
        newDayOfMonth = month + newDayOfMonth;
    }

    // If the new day of the month is greater than the last day of the month, set it to the last day of the month
    if (newDayOfMonth > lastDayOfMonth(year, month)) {
