    if (str == null || str.length() == 0) {
        return lb;
    }

    // The number of bytes to be written
    int numBytes = 0;

    // The number of characters to be written
    int numChars = str.length();

    // The current character being written
    char currChar = 0;

    // The current byte being written
    byte currByte = 0;

    // The offset of the first byte to be written
    int startByteOffset = lb.position();

    // The offset of the last byte to be written
    int endByteOffset = startByteOffset;

    // Iterate through each character in the string
    for (int i = 0; i < numChars; i++) {
        // Get the current character
        currChar = str.charAt(i);

        // Check if the current character is a valid UTF8 character
        if (currChar < 0x80) {
            // The current character is a single byte value
            currByte = (byte) currChar;
            numBytes += 1;
        } else if (currChar < 0x800) {
            // The current character requires two bytes to encode
            numBytes += 2;
        } else if (currChar < 0xD800 || currChar > 0xDFFF) {
            // The current character requires three bytes to encode
            numBytes += 3;
        } else {
            // The current character requires four bytes to encode
            numBytes += 4;
        }
    }

    // Check if the buffer has enough capacity to write the bytes
    if (lb.remaining() < numBytes) {
        // The buffer does not have enough capacity, return the current state
        return lb;
    }

    // Reset the buffer's position and limit
    lb.position(0);
    lb.limit(numBytes);

    // Iterate through each character in the string again
    for (int i = 0; i < numChars; i++) {
        // Get the current character
        currChar = str.charAt(i);

        // Check if the current character is a valid UTF8 character
        if (currChar < 0x80) {
            // The current character is a single byte value
            currByte = (byte) currChar;
            lb.put(currByte);

        } else if (currChar < 0x800) {
            // The current character requires two bytes to encode
            lb.put((byte) (0xC0 | (currChar >> 6)));
            lb.put((byte) (0x80 | (currChar & 0x3F)));

        } else if (currChar < 0xD800 || currChar > 0xDFFF) {
            // The current character requires three bytes to encode
            lb.put((byte) (0xE0 | (currChar >> 12)));
            lb.put((byte) (0x80 | ((currChar >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (currChar & 0x3F)));

