            lb.put((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.put((byte) (0x80 | (codePoint & 0x3F)));
        }
    }

    // Reset the buffer's position and limit
    lb.position(startByteOffset);
    lb.limit(endByteOffset + numBytes);

    // Return the extended buffer
    return lb;
