 *
 * @param value The input value to be converted.
 * @return The converted value.
 * @throws Exception if conversion cannot be performed successfully
 */
@Override
protected Character convertToType(Object value) throws Exception {
    // Validate the input value
    if (value == null) {
        throw new IllegalArgumentException("Input value cannot be null");
    }

    // Handle the specific case of a character
    if (value instanceof Character) {
        return (Character) value;
    }

    // Handle the specific case of a string
    if (value instanceof String) {
        String strValue = (String) value;
        if (strValue.length() != 1) {
            throw new IllegalArgumentException("Cannot convert a string with length != 1 to a Character");
        }
        return strValue.charAt(0);
    }

    // Handle the case of a numerical value
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue < Character.MIN_VALUE || intValue > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Numerical value out of range for Character type");
        }
        return (char) intValue;
    }

    // Handle the case of a boxed boolean
    if (value instanceof Boolean) {
        return ((Boolean) value).booleanValue() ? 'T' : 'F';
    }

    // Handle the case of a boxed enum
    if (value instanceof Enum) {
        return ((Enum) value).name().charAt(0);
    }

    // Handle the case of an array
    if (value.getClass().isArray()) {
        if (Array.getLength(value) != 1) {
            throw new IllegalArgumentException("Array with length != 1 cannot be converted to a Character");
        }
        return Array.get(value, 0);
    }

    // Handle the case of any other non-null value
    if (value != null) {
        throw new IllegalArgumentException("Unsupported type: " + value.getClass().getCanonicalName());
    }

    // Handle the case of null
    return null;
}

