    // Handle invalid inputs
    if (n < 2) {
      return false;
    }

    // Loop through the numbers from 2 to the square root of n
    for (int i = 2; i <= Math.sqrt(n); i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
