private void traverse(Node root, Consumer<Node> func) {
    if (root == null) {
        return;
    }

    // Apply the function to the current node
    func.accept(root);

    // Recursively traverse the left and right subtrees
    traverse(root.left, func);
    traverse(root.right, func);
}

