private void removeNode(Node node) {
    // Replace the node with its child, if it has one
    if (node.left != null && node.right != null) {
        // Find the inorder successor of the node
        Node successor = node.right;
        while (successor.left != null) {
            successor = successor.left;
        }

        // Remove the successor from the tree
        removeNode(successor);

        // Replace the node with the successor's value
        node.value = successor.value;
    } else if (node.left != null) {
        // Replace the node with its left child
        node.value = node.left.value;
        node.left = null;
    } else if (node.right != null) {
        // Replace the node with its right child
        node.value = node.right.value;
        node.right = null;
    } else {
        // The node has no children, so it can be removed
        node = null;
    }
