private String unescapeId(String input) {
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i < input.length() - 1 && input.charAt(i + 1) == '\\') {
                // escaped backslash, add one backslash to output
                sb.append('\\');
                ++i; // skip next character
            } else {
                // non-escaped backslash, add literal backslash to output
                sb.append('\\');
            }
        } else {
            // char is not a backslash, add it to output as is
            sb.append(c);
        }
    }
    return sb.toString();
}

