public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {

  // Auxiliary data structures to store the minimal separators of each edge
  Map<E, List<List<Pair<Integer, Integer>>>> sepLists = new HashMap<>();
  Map<E, Set<Pair<Integer, Integer>>> sepNodes = new HashMap<>();

  // Iterate over all edges in the graph
  for (E edge : graph.edges()) {
    // Initialize the list of minimal separators for this edge
    List<List<Pair<Integer, Integer>>> sepList = new ArrayList<>();
    sepLists.put(edge, sepList);

    // Iterate over the nodes of the neighborhood of this edge
    for (Pair<Integer, Integer> node : graph.getNeighborhood(edge.left)) {
      // If the current node is not the tail of the edge, add the edge to the list of minimal separators if it is not already present
      if (!edge.right.equals(node.left)) {
        if (!sepNodes.containsKey(edge)) {
          sepNodes.put(edge, new HashSet<>());
        }
        sepNodes.get(edge).add(node);
      }

      // Iterate over the edges incident on the current node
      for (E neighbor : graph.getIncidentEdges(node.right)) {
        // If the current edge is the tail of the neighbor, add the minimum of the node and the current edge to the list of minimal separators
        if (neighbor.right.equals(node.left)) {
          Set<Pair<Integer,Integer>> minPlusNode = new HashSet<>();
          minPlusNode.addAll(graph.getNeighborhood(node.right));
          minPlusNode.add(node);
          sepList.add(minPlusNode);
          if (!sepNodes.containsKey(neighbor)) {
            sepNodes.put(neighbor, new HashSet<>());
          }
          sepNodes.get(neighbor).addAll(minPlusNode);
        }
      }
    }
  }

  // Concatenate the lists of minimal separators for all edges and return the final result
  List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>();
  for (E edge : graph.edges()) {
    List<List<Pair<Integer, Integer>>> sepList = sepLists.get(edge);
    if (sepList != null) {
      List<Pair<Integer, Integer>> globalSepList = new ArrayList<>();
      for (List<Pair<Integer, Integer>> list : sepList) {
        globalSepList.addAll(list);
      }
      result.add(new Pair<>(globalSepList, edge));
    }
  }
  return result;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

    for (E edge : graph.edges()) {
        List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
        for (Integer node : graph.neighbors(edge.source())) {
            if (!node.equals(edge.target())) {
                // Compute the minimal separators for the node
                List<Pair<Integer, Integer>> separators = computeLocalSeparatorList(node, edge).stream()
                        .map(p -> new Pair<>(p.left, p.right))
                        .collect(Collectors.toList());
                // Add the separators to the list of minimal separators
                minimalSeparators.addAll(separators);
            }
        }
        separatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return separatorList;
}

List<Pair<List<Pair<Integer, Integer>>, E>> computeLocalSeparatorList(Integer node, E edge) {
    if (edge.source() == node) {
        return Collections.singletonList(new Pair<>(Collections.singletonList(edge), edge));
    } else if (edge.target() == node) {
        return Collections.singletonList(new Pair<>(Collections.singletonList(edge.reverse()), edge));
    }

    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E otherEdge : graph.edges()) {
        if (otherEdge != edge && otherEdge.target() == node) {
            List<Pair<Integer, Integer>> separators = computeLocalSeparatorList(node, otherEdge).stream()
                    .map(p -> new Pair<>(p.left, p.right))
                    .collect(Collectors.toList());
            separatorList.add(new Pair<>(separators, otherEdge));
        }
    }

    return separatorList;
}

