    // Open the file to read
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse the line
            String[] tokens = line.split(":");

            // Check if the line is a valid snapshot
            if (tokens.length != 3) {
                continue;
            }

            // Get the timestamp and the snapshot data
            long timestamp = Long.parseLong(tokens[0]);
            String snapshotData = tokens[2];

            // Check if the snapshot data is valid
            if (snapshotData.isEmpty()) {
                continue;
            }

            // Extract the thread ID and the stack trace
            String[] threadIdAndStackTrace = snapshotData.split("\t");

            // Check if the thread ID and stack trace are valid
            if (threadIdAndStackTrace.length != 2) {
                continue;
            }

            // Extract the thread ID and the stack trace
            long threadId = Long.parseLong(threadIdAndStackTrace[0]);
            String stackTrace = threadIdAndStackTrace[1];

            // Check if the thread ID and stack trace are valid
            if (threadId <= 0 || stackTrace.isEmpty()) {
                continue;
            }

            // Create a new thread snapshot
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(timestamp, threadId, stackTrace);

            // Check if the time range of the snapshot is within the specified time range
            boolean isWithinRange = timeRanges.stream()
                    .anyMatch(timeRange -> timeRange.contains(timestamp));

            // Add the snapshot to the list if it is within the specified time range
            if (isWithinRange) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}

